package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Set;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.Parser;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.Tag;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.is;
import static org.hamcrest.Matchers.notNullValue;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class Element_append_TriageGen0Test {

    @Test
    public void testAppendHtml() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");
        String html = "<p>Hello World!</p>";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.children().size());
        Node child = result.children().get(0);
        assertNotNull(child);
        assertEquals("p", child.tagName());
        assertEquals("Hello World!", child.text());
    }

    @Test
    public void testAppendHtmlWithExistingChild() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");
        String html = "<p>Hello World!</p>";

        // Act
        Element child = new Element(Tag.valueOf("span"), "http://www.example.com");
        element.appendChild(child);
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(2, result.children().size());
        Node firstChild = result.children().get(0);
        assertNotNull(firstChild);
        assertEquals("span", firstChild.tagName());
        Node secondChild = result.children().get(1);
        assertNotNull(secondChild);
        assertEquals("p", secondChild.tagName());
        assertEquals("Hello World!", secondChild.text());
    }

    @Test
    public void testAppendHtmlWithNullHtml() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");

        // Act
        Element result = element.append(null);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.children().size());
    }

    @Test
    public void testAppendHtmlWithEmptyHtml() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");
        String html = "";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(0, result.children().size());
    }

    @Test
    public void testAppendHtmlWithInvalidHtml() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");
        String html = "<invalid-tag>";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.children().size());
        Node child = result.children().get(0);
        assertNotNull(child);
        assertEquals("div", child.tagName());
        assertEquals(html, child.text());
    }

    @Test
    public void testAppendHtmlWithBaseUri() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "http://www.example.com");
        String html = "<p>Hello World!</p>";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.children().size());
        Node child = result.children().get(0);
        assertNotNull(child);
        assertEquals("p", child.tagName());
        assertEquals("Hello World!", child.text());
        assertEquals("http://www.example.com", child.baseUri());
    }

    @Test
    public void testAppendHtmlWithNullBaseUri() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), null);
        String html = "<p>Hello World!</p>";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.children().size());
        Node child = result.children().get(0);
        assertNotNull(child);
        assertEquals("p", child.tagName());
        assertEquals("Hello World!", child.text());
        assertNull(child.baseUri());
    }

    @Test
    public void testAppendHtmlWithEmptyBaseUri() {
        // Arrange
        Element element = new Element(Tag.valueOf("div"), "");
        String html = "<p>Hello World!</p>";

        // Act
        Element result = element.append(html);

        // Assert
        assertNotNull(result);
        assertEquals(1, result.children().size());
        Node child = result.children().get(0);
        assertNotNull(child);
        assertEquals("p", child.tagName());
        assertEquals("Hello World!", child.text());
        assertEquals("", child.baseUri());
    }
}
